  {
    "tool_call": {
      "id": "condition-env-0-1",
      "name": "get_cabin_environment",
      "arguments": {}
    },
    "observation": {
      "ok": true,
      "data": {
        "temperature_c": 28.5,
        "humidity_percent": 50.0
      },
      "error": ""
    }
  },
  {
    "tool_call": {
      "id": "condition-control-0-1",
      "name": "set_air_conditioner",
      "arguments": {
        "enabled": true
      }
    },
    "observation": {
      "ok": true,
      "data": {
        "enabled": true,
        "indicator_on": true
      },
      "error": ""
    }
  }
]

